import 'package:supabase_flutter/supabase_flutter.dart';import '../config/app_config.dart';import '../config/supabase_config.dart';
class AuthRepository{SupabaseClient get c=>SupabaseConfig.client;Future<void>signIn(String email,String password)async{if(AppConfig.demoMode)return;await c.auth.signInWithPassword(email:email,password:password);}Future<void>signUp(String email,String password,String username)async{if(AppConfig.demoMode)return;await c.auth.signUp(email:email,password:password,data:{'user_name':username});}Future<void>signOut()async{if(!AppConfig.demoMode)await c.auth.signOut();}}
